import { SuperAppEncData } from '~/entities/super-app/model/types';
import { useSetHeaderTitle } from '~/widgets/sub-layout/use-sub-layout';
import { useGetRouterState } from '~/entities/exchange/lib/use-get-router-state';
import { useOnSubmit } from '~/entities/pin/lib/use-on-submit';
import { PinInterface } from '~/entities/pin/ui/pin-interface';
import { PinInteractionMode, VerificationType } from '~/shared/api/dtos/enums';
import i18n from '~/shared/i18n/i18n';
import { useNavigate } from '~/shared/lib/hooks/use-navigate';
import { PATHS } from '~/shared/routes/paths';

export const ResetPinNumberPage = () => {
  useSetHeaderTitle(i18n.t('resetPin'));
  const { routerState: state } = useGetRouterState<SuperAppEncData>();
  const { navigate } = useNavigate();
  const { callRegPinNum } = useOnSubmit();

  return (
    <PinInterface
      type={PinInteractionMode.재설정}
      title={i18n.t('pin:titleResetPin')}
      message={i18n.t('pin:messageResetPin')}
      step={1}
      prevPin={''}
      pin={''}
      isError={false}
      handleCompleteInput={async () => {
        const response = await callRegPinNum();
        if (response) {
          if (state?.verificationType === VerificationType.FailSetUser) {
            navigate(PATHS.root, {
              replace: true,
              state: { ...state },
            });
          } else {
            navigate(PATHS.home, { replace: true });
          }
        }
      }}
    />
  );
};
